import{_ as t,K as l,a as r,c as o,b as a,k as s,q as p,ac as n}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse('{"title":"围棋：眼、死活与简单对杀","description":"区分真眼和假眼，用完整的两眼棋块理解活棋，再用角部例子练习先后手。","frontmatter":{"title":"围棋：眼、死活与简单对杀","description":"区分真眼和假眼，用完整的两眼棋块理解活棋，再用角部例子练习先后手。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"棋类入门","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"围棋入门","summary":"区分真眼和假眼，用完整的两眼棋块理解活棋，再用角部例子练习先后手。","status":"active","related":[{"title":"围棋：落子、气、提子与胜负计算","link":"/life/personal/chess/weiqi/rules","kind":"棋类入门","scope":"general","audience":"general"},{"title":"围棋：连接、断点与基本吃子技巧","link":"/life/personal/chess/weiqi/connections","kind":"棋类入门","scope":"general","audience":"general"},{"title":"围棋：从布局到收官的一盘棋复盘","link":"/life/personal/chess/weiqi/review","kind":"棋类入门","scope":"general","audience":"general"}],"prev":{"text":"围棋：连接、断点与基本吃子技巧","link":"/life/personal/chess/weiqi/connections"},"next":{"text":"围棋：从布局到收官的一盘棋复盘","link":"/life/personal/chess/weiqi/review"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"围棋：连接、断点与基本吃子技巧","link":"/life/personal/chess/weiqi/connections"},"next":{"text":"围棋：从布局到收官的一盘棋复盘","link":"/life/personal/chess/weiqi/review"}},"headers":[],"relativePath":"life/personal/chess/weiqi/life-death.md","filePath":"life/personal/chess/weiqi/life-death.md"}'),c={name:"life/personal/chess/weiqi/life-death.md"},d={class:"chess-example"},h={class:"chess-figure"};function g(f,e,u,_,m,k){const i=l("ArticleImage");return r(),o("div",null,[e[1]||(e[1]=a("h1",{id:"围棋-眼、死活与简单对杀",tabindex:"-1"},[s("围棋：眼、死活与简单对杀 "),a("a",{class:"header-anchor",href:"#围棋-眼、死活与简单对杀","aria-label":'Permalink to "围棋：眼、死活与简单对杀"'},"​")],-1)),e[2]||(e[2]=a("p",null,"一块棋暂时没有被吃，不等于已经活了。死活要看对手持续进攻时，你能否保住棋块；“做眼”是其中最基本的方法。",-1)),e[3]||(e[3]=a("h2",{id:"什么是眼",tabindex:"-1"},[s("什么是眼 "),a("a",{class:"header-anchor",href:"#什么是眼","aria-label":'Permalink to "什么是眼"'},"​")],-1)),a("div",d,[a("div",h,[a("p",null,[p(i,{src:"/images/chess/weiqi-eyes.svg",alt:"两只真眼 · C3 与 E3。橙圈是眼位；D3 把两个空点隔开。"})])]),e[0]||(e[0]=n(`<div class="chess-explanation"><p>眼是己方棋围住的内部空点。眼的关键不只是“有空”，还在于周围的边界能否保持完整。一个大空腔即使有两个空点，也可能被对手一手破坏成只能做一个眼，不能直接当作两只独立眼。</p><p>下面是 9 路棋盘的一个局部，坐标列 A～G、行 1～5，黑 X，白 O。只摆图里的黑子，其他地方空着。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>5  . . . . . . .</span></span>
<span class="line"><span>4  . X X X X X .</span></span>
<span class="line"><span>3  . X . X . X .</span></span>
<span class="line"><span>2  . X X X X X .</span></span>
<span class="line"><span>1  . . . . . . .</span></span>
<span class="line"><span>   A B C D E F G</span></span></code></pre></div><p>这是一串直接连通的黑棋，C3、E3 是两个相互分开的单点真眼。即使黑棋外侧的气都被白占住，白也不能先下 C3：黑棋还留着 E3 一口气，没有被提走，而 C3 白子自己没有气。先下 E3 同理。所以两只真眼构成基本的活形。</p><p>这里的“两眼活”建立在边界没有被切开、眼确实为真眼的前提上。不要把两处看似包围的空点数完就停止分析。</p></div>`,1))]),e[4]||(e[4]=n('<h2 id="假眼为什么会骗人" tabindex="-1">假眼为什么会骗人 <a class="header-anchor" href="#假眼为什么会骗人" aria-label="Permalink to &quot;假眼为什么会骗人&quot;">​</a></h2><p>看一个空点时，沿它四周找边界棋子：这些棋子是否属于能相互支援的棋串？有没有一颗很容易被打吃提掉？边界一旦被提走，原来的“眼”就会破掉。</p><p>新手可以用实物验证：让对方先走，尝试吃掉眼边的棋。若你被迫填进自己的眼里救棋，原先的眼可能只是假的。角部、边上和中央的判眼细节不同，不要把“对角有一颗敌子”当成通用公式。</p><h2 id="一个完整的角部对杀练习" tabindex="-1">一个完整的角部对杀练习 <a class="header-anchor" href="#一个完整的角部对杀练习" aria-label="Permalink to &quot;一个完整的角部对杀练习&quot;">​</a></h2><p>只摆黑 B1、白 A1，其他地方空，轮黑走。白 A1 的相邻点只有 B1、A2，其中 B1 已是黑子，所以只剩 A2 一口气。黑下 A2，提走 A1，黑 A2 获得 A1 等空点作为气，着法合法。</p><p>换成白先走：白下 A2，A1、A2 连接，新增气 A3、B2，白棋不再能被黑一手提掉。这说明<strong>谁先走</strong> 会改变结论；记录一道死活题时必须写清先后手。</p><p>这只是两颗子形成的最小接触战，并不涵盖有眼、共气或劫的复杂对杀。实际两块棋相互包围时，应分别记录外气、共用气和内部眼位，不能只把看到的空点各加一次就下结论。</p><h2 id="双活和劫活先怎么处理" tabindex="-1">双活和劫活先怎么处理 <a class="header-anchor" href="#双活和劫活先怎么处理" aria-label="Permalink to &quot;双活和劫活先怎么处理&quot;">​</a></h2><p>有些双方都不敢先紧气的局面可能形成双活：不是两边都有两眼，却能共同生存。有些死活依赖赢劫，叫劫活。这两类情况不能套“不到两眼全是死棋”。入门练习遇到疑似双活或劫，先保持棋盘，查规则或请人协助确认，再计分。</p><h2 id="练习与答案" tabindex="-1">练习与答案 <a class="header-anchor" href="#练习与答案" aria-label="Permalink to &quot;练习与答案&quot;">​</a></h2><ul><li>上图黑棋的眼在哪里？<strong>C3、E3。</strong> D3 是黑子，起隔开两个眼位的作用。</li><li>若删去 D3，两个空点是否仍然是原来的“两只独立眼”？<strong>不是。</strong> 内部连成一个空腔，需要重新分析谁先占关键点。</li><li>角部例中白先下 A2 后，为什么黑下 A3 不能马上提白？<strong>白还剩 B2 一口气。</strong></li></ul><p>先学会完整摆出两眼活，再学习破眼。规则依据可参阅 <a href="https://www.britgo.org/intro/intro2.html" target="_blank" rel="noopener noreferrer">英国围棋协会入门</a>；本文棋形为原创教学摆法。</p>',12))])}const x=t(c,[["render",g]]);export{b as __pageData,x as default};
